SINA_SMART["bacterio1-haemophilus"] = {"lecture":"bacterio1-haemophilus","title":"Haemophilus influenzae type b","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"bacterio1-haemophilus:e0","text":"H. influenzae: pleomorphic Gram-negative coccobacillus, nasopharyngeal commensal.","topic":"The genus Haemophilus","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-haemophilus:e1","text":"Needs X (haemin) and V (NAD) → chocolate agar, CO₂; satellitism with S. aureus.","topic":"The genus Haemophilus","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-haemophilus:e2","text":"Capsule types a-f; type b (PRP capsule) most virulent.","topic":"Antigens, virulence and pathogenesis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-haemophilus:e3","text":"Virulence: PRP capsule, pili, IgA protease, OMP, LOS.","topic":"Antigens, virulence and pathogenesis","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-haemophilus:e4","text":"Hib: invasive (meningitis, epiglottitis, sepsis) in children 6 months-2 years.","topic":"Invasive vs non-invasive disease","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-haemophilus:e5","text":"Non-typeable: otitis, sinusitis, bronchitis, COPD exacerbations, conjunctivitis.","topic":"Invasive vs non-invasive disease","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-haemophilus:e7","text":"Invasive disease: ceftriaxone/cefotaxime; ~5% β-lactamase producers.","topic":"Invasive vs non-invasive disease","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-haemophilus:e6","text":"Samples never refrigerated; diagnosis direct only.","topic":"Laboratory diagnosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-haemophilus:e8","text":"Rifampicin prophylaxis for close contacts.","topic":"Treatment and prevention","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-haemophilus:e9","text":"Conjugate vaccine (PRP-protein) at 2, 4 (6) months + booster; ~95% fall in meningitis.","topic":"Treatment and prevention","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1hivte1":"a","125qfko":"a","dd6bju":"a","1scnitz":"a","d593n5":"a","5ip6as":"a","1bu0v1i":"a","19hwy62":"a","du4qqd":"a","lp72y7":"a","113fa7z":"a","4fvrv7":"a","apedi1":"a","1t8beyh":"a","1t69acq":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"bacterio1-haemophilus:e0":{"s":0,"u":["H. influenzae: pleomorphic Gram-negative coccobacillus, nasopharyngeal commensal.","H. influenzae : small, pleomorphic Gram-negative coccobacilli (0.3-1 µm), non-motile, non-sporing; oxidase, catalase and nitrate reductase positive; facultatively anaerobic, capnophilic; an obligate parasite of the human respiratory tract, spread by droplets."],"dp":[{"h":"Why 'influenzae' is a misnomer","t":"Richard Pfeiffer isolated this bacterium from patients during the 1889-1892 influenza pandemic and believed it caused the flu, hence the name. Only in 1933 was influenza shown to be a virus; H. influenzae had been a frequent secondary invader of lungs damaged by the virus. The same partnership still matters: a viral respiratory infection damages the ciliated epithelium and mucosal defences, opening the way to bacterial superinfection by H. influenzae , pneumococcus or S. aureus . Source: history of microbiology; the lecture's pathogenesis steps."}]},"bacterio1-haemophilus:e1":{"s":0,"u":["Needs X (haemin) and V (NAD) → chocolate agar, CO₂; satellitism with S. aureus.","It is fastidious : it needs X factor (haemin) and V factor (NAD) , so it grows on chocolate agar but not on plain blood agar."],"dp":[]},"bacterio1-haemophilus:e2":{"s":1,"u":["Capsule types a-f; type b (PRP capsule) most virulent.","The Hib capsule, polyribosyl-ribitol phosphate (PRP) , is antiphagocytic and resists complement, allowing bloodstream invasion."],"dp":[]},"bacterio1-haemophilus:e3":{"s":1,"u":["Virulence: PRP capsule, pili, IgA protease, OMP, LOS.","Pili/fimbriae attach to the nasopharyngeal mucosa, IgA protease destroys mucosal IgA, OMPs and LPS aid adhesion and invasion, and LOS (endotoxin) drives inflammation.","Steps: colonisation of the nasopharynx (often silent) → local immune evasion (IgA protease) → invasion of the epithelium → bacteraemia , protected by PRP → haematogenous spread to meninges , epiglottis , lungs, joints → inflammation and tissue damage."],"dp":[]},"bacterio1-haemophilus:e4":{"s":2,"u":["Hib: invasive (meningitis, epiglottitis, sepsis) in children 6 months-2 years.","Encapsulated, mainly Hib (rarely types a, d, e, f): invasive disease, mostly in children aged 6 months to 2 years : meningitis , epiglottitis (sudden drooling, stridor, fever; airway emergency), septicaemia, septic arthritis, severe pneumonia, cellulitis."],"dp":[]},"bacterio1-haemophilus:e5":{"s":2,"u":["Non-typeable: otitis, sinusitis, bronchitis, COPD exacerbations, conjunctivitis.","Non-typeable strains (commensals of the upper airway): non-invasive infections in children and adults: otitis media, sinusitis, bronchitis, COPD exacerbations , conjunctivitis."],"dp":[]},"bacterio1-haemophilus:e7":{"s":2,"u":["Invasive disease: ceftriaxone/cefotaxime; ~5% β-lactamase producers."],"dp":[]},"bacterio1-haemophilus:e6":{"s":3,"u":["Samples never refrigerated; diagnosis direct only.","Diagnosis is direct only; there is no serological diagnosis (anti-Hib antibodies are measured only to check immunity in a vaccinated person).","Samples : blood, CSF, sputum, throat swab, pus, joint, ear or sinus aspirates; never refrigerated (sensitive to cold and drying), transported at room temperature in gelled medium within 3 hours."],"dp":[]},"bacterio1-haemophilus:e8":{"s":4,"u":["Rifampicin prophylaxis for close contacts.","Rifampicin is the chemoprophylaxis for household or daycare contacts, especially with children under 4."],"dp":[]},"bacterio1-haemophilus:e9":{"s":4,"u":["Conjugate vaccine (PRP-protein) at 2, 4 (6) months + booster; ~95% fall in meningitis.","Primary doses at 2 and 4 (and 6) months with a booster at 11-15 months; universal vaccination cut childhood Hib meningitis by about 95%.","Vaccine : plain PRP is poorly immunogenic under 2 years, so it is conjugated to a protein carrier (tetanus or diphtheria toxoid, or an outer membrane protein: PRP-OMP)."],"dp":[]}},"meta":{"1hivte1":{"a":"recall","vg":"bacterio1-haemophilus:e0/recall/1"},"125qfko":{"a":"recall","vg":"bacterio1-haemophilus:e1/recall/1"},"dd6bju":{"a":"recall","vg":"bacterio1-haemophilus:e1/recall/1"},"1scnitz":{"a":"recall","vg":"bacterio1-haemophilus:e1/recall/2"},"d593n5":{"a":"recall","vg":"bacterio1-haemophilus:e1/recall/3"},"5ip6as":{"a":"recall","vg":"bacterio1-haemophilus:e2/recall/1"},"1bu0v1i":{"a":"recall","vg":"bacterio1-haemophilus:e4/recall/1"},"19hwy62":{"a":"application","vg":"bacterio1-haemophilus:e4/application/1"},"du4qqd":{"a":"recall","vg":"bacterio1-haemophilus:e5/recall/1"},"lp72y7":{"a":"recall","vg":"bacterio1-haemophilus:e6/recall/1"},"113fa7z":{"a":"recall","vg":"bacterio1-haemophilus:e6/recall/2"},"4fvrv7":{"a":"recall","vg":"bacterio1-haemophilus:e7/recall/1"},"apedi1":{"a":"relationship","vg":"bacterio1-haemophilus:e7/relationship/1"},"1t8beyh":{"a":"recall","vg":"bacterio1-haemophilus:e8/recall/1"},"1t69acq":{"a":"recall","vg":"bacterio1-haemophilus:e9/recall/1"}},"explRev":"2153de5f5987"};
